	@Test
	void socialMediaGeneratorProducesCliques() {
		IRI follows = Values.iri(BASE, "social/follows");
		int[] cliqueSizes = jitterCliqueSizes();
		Set<IRI> cliqueUsers = new HashSet<>();
		int cliqueUserCount = 0;
		for (int size : cliqueSizes) {
			cliqueUserCount += size;
		}
		for (int user = 0; user < cliqueUserCount; user++) {
			cliqueUsers.add(socialUser(user));
		}
		Model model = generateModel(
				handler -> ThemeDataSetGenerator.generateSocialMedia(ThemeDataSetGenerator.socialMediaConfig(),
						handler),
				statement -> follows.equals(statement.getPredicate()) && cliqueUsers.contains(statement.getSubject())
						&& cliqueUsers.contains(statement.getObject()));
		int startId = 0;
		for (int size : cliqueSizes) {
			assertClique(model, follows, startId, size);
			startId += size;
		}
	}

