	@Test
	void realEstateGeneratorProducesSparseProperties() {
		IRI propertyType = Values.iri(BASE, "realestate/Property");
		IRI viewingType = Values.iri(BASE, "realestate/Viewing");
		IRI offerType = Values.iri(BASE, "realestate/Offer");
		IRI price = Values.iri(BASE, "realestate/price");
		IRI soldDate = Values.iri(BASE, "realestate/soldDate");
		Set<IRI> types = Set.of(propertyType, viewingType, offerType);
		Model model = generateModel(
				handler -> ThemeDataSetGenerator.generateRealEstate(ThemeDataSetGenerator.realEstateConfig(), handler),
				statement -> (RDF.TYPE.equals(statement.getPredicate()) && types.contains(statement.getObject()))
						|| price.equals(statement.getPredicate()) || soldDate.equals(statement.getPredicate()));
		assertFalse(model.isEmpty());
		assertTrue(model.contains(null, RDF.TYPE, propertyType));
		assertTrue(model.contains(null, RDF.TYPE, viewingType));
		assertTrue(model.contains(null, RDF.TYPE, offerType));

		int propertyCount = model.filter(null, RDF.TYPE, propertyType).size();
		int priceCount = model.filter(null, price, null).size();
		int soldCount = model.filter(null, soldDate, null).size();
		assertTrue(priceCount > propertyCount / 4 && priceCount < propertyCount * 9 / 10,
				() -> "Expected sparse price coverage but got " + priceCount + " of " + propertyCount);
		assertTrue(soldCount < propertyCount * 3 / 10,
				() -> "Expected sparse soldDate coverage but got " + soldCount + " of " + propertyCount);
	}

