	private static void assertModelMatchesStream(Model actual, Consumer<RDFHandler> generator) {
		Model expected = generateModel(generator, statement -> true);
		assertFalse(actual.isEmpty());
		assertEquals(expected, actual);
		assertEquals(expected.getNamespaces(), actual.getNamespaces());
	}

	private static Model generateTypes(Consumer<RDFHandler> generator, IRI... types) {
		Set<IRI> selectedTypes = Set.of(types);
		return generateModel(generator,
				statement -> RDF.TYPE.equals(statement.getPredicate())
						&& selectedTypes.contains(statement.getObject()));
	}

	private static Model generateModel(Consumer<RDFHandler> generator, Predicate<Statement> retain) {
		// Generate the full default dataset, retaining every statement observed by the test assertions.
		// Indexing unrelated benchmark data dominates these smoke tests' time and memory use.
		Model model = new LinkedHashModel();
		generator.accept(new AbstractRDFHandler() {
			@Override
			public void handleNamespace(String prefix, String uri) {
				model.setNamespace(prefix, uri);
			}

			@Override
			public void handleStatement(Statement statement) {
				if (retain.test(statement)) {
					model.add(statement);
				}
			}
		});
		return model;
	}

	private static void assertClique(Model model, IRI follows, int startId, int size) {
		for (int i = 0; i < size; i++) {
			IRI source = socialUser(startId + i);
			for (int j = 0; j < size; j++) {
				if (i == j) {
					continue;
				}
				IRI target = socialUser(startId + j);
				assertTrue(model.contains(source, follows, target),
						() -> "Missing follows edge " + source + " -> " + target);
			}
		}
	}

	private static IRI socialUser(int id) {
		return Values.iri(BASE, "social/user/" + id);
	}

	private static int[] jitterCliqueSizes() {
		Random jitter = new Random(DEFAULT_SEED ^ JITTER_SEED_XOR);
		int userCount = jitterInt(jitter, DEFAULT_USER_COUNT, 1);
		jitterInt(jitter, DEFAULT_TAG_COUNT, 1);
		return jitterCliqueSizes(jitter, DEFAULT_CLIQUE_SIZES, userCount);
	}

	private static int jitterInt(Random random, int base, int minValue) {
		int delta = base / 2;
		int min = Math.max(minValue, base - delta);
		int max = Math.max(min, base + delta);
		if (min == max) {
			return min;
		}
		return min + random.nextInt(max - min + 1);
	}

	private static int[] jitterCliqueSizes(Random random, int[] baseSizes, int maxTotal) {
		List<Integer> sizes = new ArrayList<>(baseSizes.length);
		int remaining = maxTotal;
		for (int base : baseSizes) {
			if (remaining < 2) {
				break;
			}
			int size = jitterInt(random, base, 2);
			if (size > remaining) {
				size = remaining;
			}
			if (size < 2) {
				break;
			}
			sizes.add(size);
			remaining -= size;
		}
		int[] result = new int[sizes.size()];
		for (int i = 0; i < sizes.size(); i++) {
			result[i] = sizes.get(i);
		}
		return result;
	}
